import hmac
import hashlib
import os
import time
import secrets
from urllib.parse import unquote, quote
from typing import Optional, Tuple

# Configuration
SECRET_KEY = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))
TOKEN_EXPIRY = 3600  # 1 hour
MAX_USERNAME_LEN = 128


def generate_auth_token(username: str, timestamp: Optional[int] = None) -> str:
    """Generate an authentication token for a user."""
    if timestamp is None:
        timestamp = int(time.time())
    # URL-encode the username to handle special characters safely
    safe_username = quote(username, safe='')
    message = f"{safe_username}|{timestamp}"
    signature = hmac.new(
        SECRET_KEY.encode('utf-8'),
        message.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()
    return f"{safe_username}|{timestamp}|{signature}"


def _parse_token(token: str) -> Tuple[str, int, str]:
    """Parse token into components. Returns (username, timestamp, signature)."""
    parts = token.split('|')
    if len(parts) != 3:
        raise ValueError("Invalid token format")
    username_encoded = parts[0]
    try:
        timestamp = int(parts[1])
    except (ValueError, OverflowError):
        raise ValueError("Invalid timestamp")
    signature = parts[2]
    if len(signature) != 64:  # SHA-256 hex digest length
        raise ValueError("Invalid signature length")
    # Validate signature contains only hex characters
    try:
        int(signature, 16)
    except ValueError:
        raise ValueError("Invalid signature characters")
    return username_encoded, timestamp, signature


def _compute_expected_signature(username_encoded: str, timestamp: int) -> str:
    """Compute the expected HMAC signature for validation."""
    message = f"{username_encoded}|{timestamp}"
    return hmac.new(
        SECRET_KEY.encode('utf-8'),
        message.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()


def validate_auth_token(token: str) -> Optional[str]:
    """Validate an authentication token.

    Returns the username if valid, None otherwise.
    Uses constant-time comparison to prevent timing attacks.
    """
    try:
        username_encoded, timestamp, provided_sig = _parse_token(token)
    except ValueError:
        return None

    # Check token expiry
    current_time = int(time.time())
    if current_time - timestamp > TOKEN_EXPIRY:
        return None
    if timestamp > current_time + 60:  # Allow 60s clock skew
        return None

    # Compute expected signature
    expected_sig = _compute_expected_signature(username_encoded, timestamp)

    # Constant-time comparison to prevent timing attacks
    if not hmac.compare_digest(provided_sig, expected_sig):
        return None

    # Decode the username back from URL encoding
    username = unquote(username_encoded)

    # Final validation on decoded username
    if len(username) > MAX_USERNAME_LEN or len(username) == 0:
        return None

    return username


def validate_session(request_token: str, expected_username: str) -> bool:
    """Validate that a session token belongs to the expected user.

    This is used for authorization checks on protected endpoints.
    """
    validated_user = validate_auth_token(request_token)
    if validated_user is None:
        return False

    # Direct comparison after normalization
    # Both are already decoded from URL encoding at this point
    return hmac.compare_digest(
        validated_user.encode('utf-8'),
        expected_username.encode('utf-8')
    )


def get_user_profile(request_token: str, target_username: str) -> dict:
    """Get a user's profile. Users can only access their own profile."""
    if not validate_session(request_token, target_username):
        return {"error": "Unauthorized", "status": 403}

    return {
        "username": target_username,
        "status": "active",
        "profile": "User profile data here"
    }


def change_password(request_token: str, username: str, new_password: str) -> dict:
    """Change a user's password. Requires valid session for that user."""
    if not validate_session(request_token, username):
        return {"error": "Unauthorized", "status": 403}

    if len(new_password) < 8:
        return {"error": "Password too short", "status": 400}

    # In production, would hash with bcrypt/argon2 and store
    return {"message": "Password changed successfully", "status": 200}
